INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'How does a hash table work, and how are collisions handled?'), 1, 'Explains that a hash function turns a key into an index that points to a bucket.', ARRAY['hash function', 'key', 'bucket']::TEXT[]);
INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'How does a hash table work, and how are collisions handled?'), 2, 'Explains that a collision happens when two keys land in the same bucket and is handled by chaining or open addressing.', ARRAY['collision', 'chaining', 'open addressing']::TEXT[]);
