INSERT INTO question_library (category, difficulty, question_type, prompt, expected_keywords) VALUES ('Data Structures', 'Hard', 'Technical', 'Explain how a binary search tree works and why it can become unbalanced.', ARRAY['left', 'right', 'smaller', 'larger', 'o(log n)', 'o(n)', 'balanced', 'avl', 'red-black']::TEXT[]) ON CONFLICT (prompt) DO UPDATE SET category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, expected_keywords = EXCLUDED.expected_keywords;
