INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'Explain how a binary search tree works and why it can become unbalanced.'), 2, 'States that search takes O(log n) time when the tree is balanced.', ARRAY['o(log n)', 'balanced']::TEXT[]);
