INSERT INTO question_library (category, difficulty, question_type, prompt, expected_keywords) VALUES ('Python', 'Medium', 'Technical', 'What is the difference between a shallow copy and a deep copy?', ARRAY['reference', 'nested', 'copy', 'deepcopy', 'object', 'independent']::TEXT[]) ON CONFLICT (prompt) DO UPDATE SET category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, expected_keywords = EXCLUDED.expected_keywords;
