INSERT INTO question_library (category, difficulty, question_type, prompt, expected_keywords) VALUES ('Python', 'Hard', 'Technical', 'What is the Global Interpreter Lock (GIL) in Python?', ARRAY['thread', 'cpython', 'lock', 'one thread', 'multiprocessing', 'cpu-bound', 'i/o-bound']::TEXT[]) ON CONFLICT (prompt) DO UPDATE SET category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, expected_keywords = EXCLUDED.expected_keywords;
