INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'What is the Global Interpreter Lock (GIL) in Python?'), 1, 'Explains that the GIL is a lock in CPython that lets only one thread run Python bytecode at a time.', ARRAY['cpython', 'lock', 'one thread']::TEXT[]);
INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'What is the Global Interpreter Lock (GIL) in Python?'), 2, 'Explains that it limits CPU-bound threads, so multiprocessing is used for that work, while I/O-bound threads still benefit.', ARRAY['cpu-bound', 'multiprocessing', 'i/o-bound']::TEXT[]);
